{
  "interpretation": {
    "name": "TightenVariantFastenersLine2AndReturnTool",
    "scope": {"line": 2, "station": "st2", "tool": "NR7", "variant": "F30"},
    "goal": "Tighten the fasteners of variant F30 at station st2 of line 2 with the shared nutrunner NR7, evaluate and record the result, then return the tool to the crib and release the reservation so other lines are not blocked.",
    "constraints": [
      "The tool must be reserved before use and released after it is returned to the crib",
      "The tool must be transported to st2 before configure-tool and tighten-fasteners",
      "The tightening program is obtained only from get-program (no numeric process values in the Recipe)",
      "The tightening must be evaluated and recorded for traceability",
      "Transport steps are delegated to agvexecutor",
      "Every tool-using step renews the lease and depends on reserve-tool; each single step must be shorter than the 120 s lease"
    ],
    "preference": "Release the shared tool as soon as it is back in the crib.",
    "priority": "normal",
    "horizon": "Single execution, starting now",
    "requested_capabilities": [],
    "omit_services": []
  },
  "recipe": {
    "name": "line2-tighten-f30-and-return-nr7",
    "first_action": "prepare",
    "actions": [
      {
        "name": "prepare",
        "next": "bring-tool",
        "steps": [
          {
            "name": "reserve-tool-step",
            "service": "reserve-tool",
            "next": [],
            "dep": [],
            "executor": null,
            "params": {}
          },
          {
            "name": "get-program-step",
            "service": "get-program",
            "next": [],
            "dep": [],
            "executor": null,
            "params": {}
          }
        ]
      },
      {
        "name": "bring-tool",
        "next": "tighten",
        "steps": [
          {
            "name": "transport-to-station-step",
            "service": "transport-tool",
            "next": [],
            "dep": ["reserve-tool-step"],
            "executor": "agvexecutor",
            "params": {"to": "station"}
          }
        ]
      },
      {
        "name": "tighten",
        "next": "quality",
        "steps": [
          {
            "name": "configure-tool-step",
            "service": "configure-tool",
            "next": ["tighten-fasteners-step"],
            "dep": ["get-program-step", "reserve-tool-step"],
            "executor": null,
            "params": {}
          },
          {
            "name": "tighten-fasteners-step",
            "service": "tighten-fasteners",
            "next": [],
            "dep": ["configure-tool-step", "reserve-tool-step"],
            "executor": null,
            "params": {}
          }
        ]
      },
      {
        "name": "quality",
        "next": "return-tool",
        "steps": [
          {
            "name": "evaluate-tightening-step",
            "service": "evaluate-tightening",
            "next": [],
            "dep": ["tighten-fasteners-step", "get-program-step"],
            "executor": null,
            "params": {}
          },
          {
            "name": "record-tightening-step",
            "service": "record-tightening",
            "next": [],
            "dep": ["tighten-fasteners-step"],
            "executor": null,
            "params": {}
          }
        ]
      },
      {
        "name": "return-tool",
        "next": null,
        "steps": [
          {
            "name": "transport-to-crib-step",
            "service": "transport-tool",
            "next": ["release-tool-step"],
            "dep": ["reserve-tool-step"],
            "executor": "agvexecutor",
            "params": {"to": "crib"}
          },
          {
            "name": "release-tool-step",
            "service": "release-tool",
            "next": [],
            "dep": ["reserve-tool-step"],
            "executor": null,
            "params": {}
          }
        ]
      }
    ]
  }
}
